                reset();
            } else {
                unknownSequence(b);
            }
            break;
        case ESC_CSI_QUESTIONMARK:
            doCsiQuestionMark(b);
            break;
        case ESC_CSI_BIGGERTHAN:
            doCsiBiggerThan(b);
            break;

