            int red = getArg(i + 2, 0, false);
            int green = getArg(i + 3, 0, false);
            int blue = getArg(i + 4, 0, false);
            if (red < 0 || green < 0 || blue < 0 || red > 255 || green > 255 || blue > 255) {
