private void doEscByte() {
    if (mEscapeState == ESC_P) {
        // Ignore escape when reading device control sequence — it may be part of the string terminator.
    } else if (mEscapeState != ESC_OSC) {
        startEscapeSequence();
    } else {
        doOsc(27);
    }
