/**
 * Send a Unicode code point to the screen.
 *
 * @param codePoint The code point of the character to display
 */
private void emitCodePoint(int codePoint) {
    mLastEmittedCodePoint = codePoint;
    if (mUseLineDrawingUsesG0 ? mUseLineDrawingG0 : mUseLineDrawingG1) {
        codePoint = translateLineDrawingCodePoint(codePoint);
    }

    final boolean autoWrap = isDecsetInternalBitSet(DECSET_BIT_AUTOWRAP);
    final int displayWidth = WcWidth.width(codePoint);
    final boolean cursorInLastColumn = mCursorCol == mRightMargin - 1;

    if (autoWrap) {
        if (cursorInLastColumn && ((mAboutToAutoWrap && displayWidth == 1) || displayWidth == 2)) {
            mScreen.setLineWrap(mCursorRow);
            mCursorCol = mLeftMargin;
            if (mCursorRow + 1 < mBottomMargin) {
                mCursorRow++;
            } else {
                scrollDownOneLine();
            }
        }
    } else if (cursorInLastColumn && displayWidth == 2) {
        // The behaviour when a wide character is output with cursor in the last column when
        // autowrap is disabled is not obvious - it's ignored here.
        return;
    }

    if (mInsertMode && displayWidth > 0) {
        // Move character to right one space.
        int destCol = mCursorCol + displayWidth;
        if (destCol < mRightMargin)
            mScreen.blockCopy(mCursorCol, mCursorRow, mRightMargin - destCol, 1, destCol, mCursorRow);
    }

    int offsetDueToCombiningChar = ((displayWidth <= 0 && mCursorCol > 0 && !mAboutToAutoWrap) ? 1 : 0);
    int column = mCursorCol - offsetDueToCombiningChar;

    // Fix TerminalRow.setChar() ArrayIndexOutOfBoundsException index=-1 exception reported
    // The offsetDueToCombiningChar would never be 1 if mCursorCol was 0 to get column/index=-1,
    // so was mCursorCol changed after the offsetDueToCombiningChar conditional by another thread?
    // TODO: Check if there are thread synchronization issues with mCursorCol and mCursorRow, possibly causing others bugs too.
    if (column < 0) column = 0;
    mScreen.setChar(column, mCursorRow, codePoint, getStyle());

    if (autoWrap && displayWidth > 0)
        mAboutToAutoWrap = (mCursorCol == mRightMargin - displayWidth);

    mCursorCol = Math.min(mCursorCol + displayWidth, mRightMargin - 1);
}

/** Translates VT100 special-graphics (G0/G1 line-drawing) code points to Unicode. */
private static int translateLineDrawingCodePoint(int codePoint) {
    // http://www.vt100.net/docs/vt102-ug/table5-15.html.
    switch (codePoint) {
        case '_': return ' ';    // Blank.
        case '`': return '◆';   // Diamond.
        case '0': return '█';   // Solid block.
        case 'a': return '▒';   // Checker board.
        case 'b': return '␉';   // Horizontal tab.
        case 'c': return '␌';   // Form feed.
        case 'd': return '\r';  // Carriage return.
        case 'e': return '␊';   // Linefeed.
        case 'f': return '°';   // Degree.
        case 'g': return '±';   // Plus-minus.
        case 'h': return '\n';  // Newline.
        case 'i': return '␋';   // Vertical tab.
        case 'j': return '┘';   // Lower right corner.
        case 'k': return '┐';   // Upper right corner.
        case 'l': return '┌';   // Upper left corner.
        case 'm': return '└';   // Left left corner.
        case 'n': return '┼';   // Crossing lines.
        case 'o': return '⎺';   // Horizontal line - scan 1.
        case 'p': return '⎻';   // Horizontal line - scan 3.
        case 'q': return '─';   // Horizontal line - scan 5.
        case 'r': return '⎼';   // Horizontal line - scan 7.
        case 's': return '⎽';   // Horizontal line - scan 9.
        case 't': return '├';   // T facing rightwards.
        case 'u': return '┤';   // T facing leftwards.
        case 'v': return '┴';   // T facing upwards.
        case 'w': return '┬';   // T facing downwards.
        case 'x': return '│';   // Vertical line.
        case 'y': return '≤';   // Less than or equal to.
        case 'z': return '≥';   // Greater than or equal to.
        case '{': return 'π';   // Pi.
        case '|': return '≠';   // Not equal to.
        case '}': return '£';   // UK pound.
        case '~': return '·';   // Centered dot.
        default:  return codePoint;
    }
}

